"""Unified API error envelope.

Every error response has the same shape:
    {"error": {"code": "...", "message": "...", "details": ...}, "correlation_id": "..."}
Handlers must never leak tokens, payloads or stack traces to the client.
"""

import logging
from typing import Any

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException

from app.logging_setup import correlation_id_var

logger = logging.getLogger(__name__)


class ApiError(Exception):
    """Domain-level error with a stable machine-readable code."""

    def __init__(
        self,
        code: str,
        message: str,
        *,
        status_code: int = 400,
        details: Any = None,
    ) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.status_code = status_code
        self.details = details


def _envelope(
    status_code: int,
    code: str,
    message: str,
    details: Any = None,
) -> JSONResponse:
    body: dict[str, Any] = {
        "error": {"code": code, "message": message, "details": details},
        "correlation_id": correlation_id_var.get(),
    }
    return JSONResponse(status_code=status_code, content=body)


def install_error_handlers(app: FastAPI) -> None:
    @app.exception_handler(ApiError)
    async def handle_api_error(request: Request, exc: ApiError) -> JSONResponse:
        return _envelope(exc.status_code, exc.code, exc.message, exc.details)

    @app.exception_handler(RequestValidationError)
    async def handle_validation_error(
        request: Request, exc: RequestValidationError
    ) -> JSONResponse:
        return _envelope(422, "VALIDATION_ERROR", "Request validation failed", exc.errors())

    @app.exception_handler(StarletteHTTPException)
    async def handle_http_exception(
        request: Request, exc: StarletteHTTPException
    ) -> JSONResponse:
        detail = exc.detail if isinstance(exc.detail, str) else "HTTP error"
        return _envelope(exc.status_code, "HTTP_ERROR", detail)

    @app.exception_handler(Exception)
    async def handle_unexpected_error(request: Request, exc: Exception) -> JSONResponse:
        logger.exception("Unhandled exception")
        return _envelope(500, "INTERNAL_ERROR", "Internal server error")

import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

// Dev proxy forwards health checks to the local backend (uvicorn on :8000).
export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      "/healthz": "http://localhost:8000",
      "/readyz": "http://localhost:8000",
    },
  },
});

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import App from "./App";

const rootElement = document.getElementById("root");
if (!rootElement) {
  throw new Error("Root element #root not found");
}

createRoot(rootElement).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

export interface HealthPayload {
  status: "ok";
  version?: string;
}

export type HealthPhase = "ok" | "invalid";

/**
 * Validates a /healthz response payload. Kept pure so it is testable
 * without a DOM environment.
 */
export function parseHealth(payload: unknown): HealthPhase {
  if (
    typeof payload === "object" &&
    payload !== null &&
    "status" in payload &&
    (payload as HealthPayload).status === "ok"
  ) {
    return "ok";
  }
  return "invalid";
}

import { describe, expect, it } from "vitest";

import { parseHealth } from "./health";

describe("parseHealth", () => {
  it("accepts a valid health payload", () => {
    expect(parseHealth({ status: "ok", version: "0.1.0" })).toBe("ok");
  });

  it("rejects payloads without status ok", () => {
    expect(parseHealth({ status: "error" })).toBe("invalid");
  });

  it("rejects non-object payloads", () => {
    expect(parseHealth(null)).toBe("invalid");
    expect(parseHealth("ok")).toBe("invalid");
  });
});

import { useEffect, useState } from "react";

import { parseHealth, type HealthPhase } from "./lib/health";

export default function App() {
  const [phase, setPhase] = useState<HealthPhase>("invalid");
  const [version, setVersion] = useState<string>("");

  useEffect(() => {
    fetch("/healthz")
      .then((response) => response.json())
      .then((payload: unknown) => {
        setPhase(parseHealth(payload));
        if (payload !== null && typeof payload === "object" && "version" in payload) {
          setVersion(String((payload as { version?: unknown }).version ?? ""));
        }
      })
      .catch(() => setPhase("invalid"));
  }, []);

  return (
    <main style={{ fontFamily: "sans-serif", padding: "2rem" }}>
      <h1>Support Hub</h1>
      <p>
        Backend health: <strong>{phase === "ok" ? "OK" : "unavailable"}</strong>
        {version ? ` (v${version})` : ""}
      </p>
      <p>Bootstrap skeleton — operator workspace arrives at stage 8.</p>
    </main>
  );
}

